for o in obs.values():assert sha(o['previewPath'])==o['previewSha256']
b=read('audits/review-snapshots/W04-L16-v2-contracts.json');reveal=read('audits/W04-L16-v2-contracts-author-reveal.json');assert sha('audits/review-snapshots/W04-L16-v2-contracts.json')==reveal['snapshotSha256'];m=read(e['manifestPath']);assert sha(e['manifestPath'])==e['manifestSha256'];byid={q['id']:q for q in b['questions']}
