 reviews.append(dict(id=q['id']+'-v2-contracts-independent',questionId=q['id'],questionVersion=2,questionSha256=question_hash(q),reviewerId=R,decision='verified',reviewedAt=now,sourceVersions=e['sourceVersions'],reviewedSlideIds=[f'lectures-p{p:04}' for p in pages],independentAnswerOptionIds=a['independentAnswerOptionIds'],solvedBeforeAnswerSeen=False,checks={k:True for k in ['sourceSupport','assumptions','answerSet','distractors','calculations','figureFidelity','explanation','difficulty','duplication']},reasoning=reason,findings=[],blindAnswersPath=ap,blindAnswersSha256=sha(ap),independentSolvedAt=a['solvedAt'],priorAuthorExposure=True,exposureNote=a['exposureNote'],computationsPath='audits/W04-L16-v2-independent-checks.json',sourceInspectionEvidence=[{k:obs[p][k] for k in ['physicalPage','inspectorId','previewPath','previewSha256','dimensions','inspectedAt']} for p in pages]))
